CREATE SEQUENCE nih_s;
CREATE TABLE nih_t(id int, b bit(4), s text, n numeric);
CREATE TABLE nih_z(x int);
INSERT INTO nih_t VALUES (1, B'1010', 'pear', 1.25), (2, B'0110', 'apple', NULL), (3, B'1111', 'fig', 10.5), (4, NULL, NULL, -3);
INSERT INTO nih_z VALUES (1), (2);
SELECT id, (SELECT x + (SELECT nextval('nih_s')) FROM nih_z WHERE x <= t.id ORDER BY x DESC LIMIT 1) FROM nih_t t ORDER BY id;
SELECT id, EXISTS (SELECT 1 FROM nih_z WHERE x = t.id AND x IN (SELECT max(x) FROM nih_z)) FROM nih_t t ORDER BY id;
SELECT id, (SELECT count(*) FROM nih_z WHERE x < t.id AND x <> ALL (SELECT x - 5 FROM nih_z)) FROM nih_t t ORDER BY id;
SELECT id, (SELECT t.id * (SELECT sum(x) FROM nih_z)) FROM nih_t t ORDER BY id;
SELECT id, (SELECT max(x) FROM nih_z WHERE x < t.id GROUP BY x > (SELECT min(x) FROM nih_z) ORDER BY 1 LIMIT 1) FROM nih_t t ORDER BY id;
SELECT max(s), min(s), sum(n), avg(n), variance(n), bit_or(b), bit_and(b), bit_xor(b), min(ROW(id, s)::text), max(ARRAY[id, length(s)]) FROM nih_t;
SELECT id % 2, max(s || id), sum(n * id), stddev_samp(n), bool_and(n > 0), every(s <> 'x'), corr(id, n) FROM nih_t GROUP BY 1 ORDER BY 1;
SELECT max(s), sum(n) FROM nih_t WHERE id > 10;
SELECT count(*), max(v), min(w) FROM (SELECT s || repeat('-', id) AS v, n * 2 AS w FROM nih_t LIMIT 10) d;
SELECT id, (SELECT max(x::text || t.s) FROM nih_z) FROM nih_t t ORDER BY id;
